        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def get_top_valid(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = book.get(oid)
            if info is None or not info['active'] or info['remaining'] <= 0:
                heapq.heappop(heap)
                continue
            return top
